-- Korrektur: Umlaute in den DevOps-Lieferungen vom 2026-10-10 (fuer -> für, Groesse -> Größe).
-- Datei: content/sql/2026-10-10-devops-platform-cloud-umlaut-fix.sql
-- Ändert nur question, answer und note der aufgeführten Fragen und nur, solange der Text in der
-- Datenbank noch exakt einer bekannten früheren Fassung entspricht: der Originallieferung oder
-- dem Stand nach der ersten Fassung dieses Skripts. Fehlende, bereits korrigierte oder inzwischen
-- anders bearbeitete Fragen bleiben unverändert. Stufen, Scores, Zähler und difficulty_votes
-- werden nicht angefasst. Mehrfaches Ausführen ist unschädlich.
BEGIN;
SELECT pg_advisory_xact_lock(391002);

CREATE TEMP TABLE umlaut_fixes (
  topic_id varchar(64) NOT NULL,
  id varchar(64) NOT NULL,
  stand varchar(40) NOT NULL,
  old_question varchar(500) NOT NULL,
  new_question varchar(500) NOT NULL,
  old_answer varchar(500) NOT NULL,
  new_answer varchar(500) NOT NULL,
  old_note varchar(500),
  new_note varchar(500),
  PRIMARY KEY (topic_id, id, stand)
) ON COMMIT DROP;

-- 279 Fragen mit geänderter Schreibweise, je bekannter früherer Fassung eine Zeile

CREATE TEMP TABLE umlaut_fix_status ON COMMIT DROP AS
SELECT t.topic_id, t.id, t.new_question, t.new_answer, t.new_note,
  CASE
    WHEN q.id IS NULL THEN 'fehlt'
    WHEN (q.question, q.answer, q.note) IS NOT DISTINCT FROM (t.new_question, t.new_answer, t.new_note)
      THEN 'bereits korrigiert'
    WHEN EXISTS (
      SELECT 1 FROM umlaut_fixes f
      WHERE f.topic_id = t.topic_id AND f.id = t.id
        AND (q.question, q.answer, q.note) IS NOT DISTINCT FROM (f.old_question, f.old_answer, f.old_note)
    ) THEN 'korrigiert'
    ELSE 'abweichend'
  END AS status
FROM (SELECT DISTINCT topic_id, id, new_question, new_answer, new_note FROM umlaut_fixes) t
LEFT JOIN questions q ON q.topic_id = t.topic_id AND q.id = t.id;

UPDATE questions q
SET question = s.new_question, answer = s.new_answer, note = s.new_note
FROM umlaut_fix_status s
WHERE s.status = 'korrigiert' AND q.topic_id = s.topic_id AND q.id = s.id;

-- Ergebnis im Meldungen-Tab von pgAdmin bzw. als NOTICE in psql.
DO $$
DECLARE
  r record;
BEGIN
  FOR r IN SELECT status, count(*) AS n FROM umlaut_fix_status GROUP BY status ORDER BY status LOOP
    RAISE NOTICE '%: %', r.status, r.n;
  END LOOP;
  FOR r IN SELECT topic_id, id FROM umlaut_fix_status WHERE status = 'abweichend' ORDER BY id LOOP
    RAISE NOTICE 'Nicht geändert, Text weicht ab: %/%', r.topic_id, r.id;
  END LOOP;
END $$;

COMMIT;
